package initdb

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"

	"github.com/goopg/goopg/internal/catalog"
	"github.com/goopg/goopg/internal/executor"
)

// pgDescriptionRow is one pg_description (objoid, classoid, objsubid,
// description) or pg_shdescription (objsubid 0, unused) row. The generated
// rows live in package catalog, which also seeds goopg's comment store.
type pgDescriptionRow = catalog.InitdbDescription

// bootstrapPgDescription writes the built-in object descriptions a PostgreSQL
// 18.3 initdb leaves (catalog.PGInitdbDescriptions / PGInitdbShdescriptions, generated by
// scripts/gen-pg-description.py) to pg_description (base/{1,5}/2609, index
// 2675 on (objoid, classoid, objsubid)) and pg_shdescription (global/2396,
// index 2397 on (objoid, classoid)). Without them obj_description() and psql's
// \df+ / \do+ "Description" column are empty on a PG node. M0149-0001g slice 19.
func bootstrapPgDescription(dataDir string) error {
	cols := []catalog.Column{
		{Name: "objoid", Type: catalog.Type{Name: "oid"}},
		{Name: "classoid", Type: catalog.Type{Name: "oid"}},
		{Name: "objsubid", Type: catalog.Type{Name: "int4"}},
		{Name: "description", Type: catalog.Type{Name: "text"}},
	}
	local := append(append([]pgDescriptionRow{}, catalog.PGInitdbDescriptions...), pgDescriptionInitdbTS...) // + snowball TS objects (slice 21)
	rows := make([]executor.Row, len(local))
	for i, r := range local {
		rows[i] = executor.Row{executor.NewIntDatum(int64(r.ObjOID)), executor.NewIntDatum(int64(r.ClassOID)),
			executor.NewIntDatum(int64(r.ObjSubID)), executor.NewStringDatum(r.Description)}
	}
	tids, err := writeMultiPageHeapRows(dataDir, "2609", cols, rows)
	if err != nil {
		return fmt.Errorf("pg_description heap: %w", err)
	}
	if err := writeDescriptionIndex(dataDir, []string{"base/1", "base/5"}, "2675", local, tids, 3); err != nil {
		return err
	}
	shCols := []catalog.Column{cols[0], cols[1], cols[3]}
	shRows := make([]executor.Row, len(catalog.PGInitdbShdescriptions))
	for i, r := range catalog.PGInitdbShdescriptions {
		shRows[i] = executor.Row{executor.NewIntDatum(int64(r.ObjOID)), executor.NewIntDatum(int64(r.ClassOID)),
			executor.NewStringDatum(r.Description)}
	}
	shTids, err := writeSharedHeapRows(dataDir, "2396", shCols, shRows)
	if err != nil {
		return fmt.Errorf("pg_shdescription heap: %w", err)
	}
	return writeDescriptionIndex(dataDir, []string{"global"}, "2397", catalog.PGInitdbShdescriptions, shTids, 2)
}

// writeDescriptionIndex bulk-builds a btree keyed on (objoid, classoid[,
// objsubid]) — all three are 4-byte keys (objsubid int4 is never negative here).
func writeDescriptionIndex(dataDir string, dirs []string, file string, rows []pgDescriptionRow, tids []heapTID, nkeys int) error {
	type item struct {
		r   pgDescriptionRow
		tid heapTID
	}
	items := make([]item, len(rows))
	for i := range rows {
		items[i] = item{rows[i], tids[i]}
	}
	sort.Slice(items, func(i, j int) bool {
		a, b := items[i].r, items[j].r
		if a.ObjOID != b.ObjOID {
			return a.ObjOID < b.ObjOID
		}
		if a.ClassOID != b.ClassOID {
			return a.ClassOID < b.ClassOID
		}
		return a.ObjSubID < b.ObjSubID
	})
	tuples := make([][]byte, len(items))
	for i, it := range items {
		keys := []uint32{it.r.ObjOID, it.r.ClassOID, uint32(it.r.ObjSubID)}[:nkeys]
		tuples[i] = pgBuildIndexTupleOidKeys(it.tid.Block, it.tid.Offset, keys)
	}
	if len(tuples) == 0 {
		return nil
	}
	img, err := pgBuildBtreeBulkLoadSized(tuples, len(tuples[0]), uint16(nkeys))
	if err != nil {
		return fmt.Errorf("index %s: %w", file, err)
	}
	for _, d := range dirs {
		if err := os.WriteFile(filepath.Join(dataDir, d, file), img, 0o600); err != nil {
			return err
		}
	}
	return nil
}
